func init() {
	packageListCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	packageGetCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	packageGetCmd.Flags().String("name", "", "The package, such as curl")
	_ = packageGetCmd.MarkFlagRequired("name")
	packageCreateCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	packageCreateCmd.Flags().String("name", "", "The package to install, such as curl")
	_ = packageCreateCmd.MarkFlagRequired("name")
	packageCreateCmd.Flags().String("version", "", "The version to install, such as 8.5.0-2ubuntu10; the newest when empty")
	packageDeleteCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	packageDeleteCmd.Flags().String("name", "", "The package to remove, such as curl")
	_ = packageDeleteCmd.MarkFlagRequired("name")
	clicommand.AddCommands(Group, packageListCmd, packageGetCmd, packageCreateCmd, packageDeleteCmd)
}
